import { defineNitroPlugin } from "nitropack/runtime";
import pdfMake from "pdfmake/build/pdfmake";
import { cdnFonts, fontDescriptors, fontVfs, useDefaultRoboto } from "#pdfmake-fonts";
export default defineNitroPlugin(async (nitroApp) => {
  if (Object.keys(fontVfs).length > 0) {
    pdfMake.addVirtualFileSystem(fontVfs);
  }
  if (useDefaultRoboto) {
    const vfsFontsModule = await import("pdfmake/build/vfs_fonts.js");
    const vfsData = vfsFontsModule.default ?? vfsFontsModule;
    pdfMake.addVirtualFileSystem(vfsData);
  }
  const allFonts = {
    ...fontDescriptors,
    ...cdnFonts
  };
  if (useDefaultRoboto) {
    allFonts.Roboto ??= {
      normal: "Roboto-Regular.ttf",
      bold: "Roboto-Medium.ttf",
      italics: "Roboto-Italic.ttf",
      bolditalics: "Roboto-MediumItalic.ttf"
    };
  }
  pdfMake.addFonts(allFonts);
  nitroApp.$pdfMake = pdfMake;
});
